import Model from 'flarum/common/Model';

/** A single recruit row on the board. */

/** The forum's recruiting board: GET /api/recruiting-boards/1. */
export default class RecruitingBoard extends Model {
  year = Model.attribute('year');
  recruits = Model.attribute('recruits');
  error = Model.attribute('error');
}
flarum.reg.add('ernestdefoe-recruiting', 'forum/models/RecruitingBoard', RecruitingBoard);